/**
 * Stardust Service Worker - Caches Pyodide and static assets
 * Generated by stardust build
 */

const CACHE_VERSION = 'stardust-v1776640284';
const PYODIDE_CACHE = 'stardust-pyodide-v1';

// Static assets to precache (absolute paths for correct resolution)
const PRECACHE_URLS = [
    '/',
    '/index.html',
    '/static/stardust-runtime.js',
    '/static/datastar.js'
];

// Install: precache static assets
self.addEventListener('install', (event) => {
    event.waitUntil(
        caches.open(CACHE_VERSION)
            .then(cache => cache.addAll(PRECACHE_URLS))
            .then(() => self.skipWaiting())
    );
});

// Activate: clean old caches
self.addEventListener('activate', (event) => {
    event.waitUntil(
        caches.keys().then(cacheNames => {
            return Promise.all(
                cacheNames
                    .filter(name => name !== CACHE_VERSION && name !== PYODIDE_CACHE)
                    .map(name => caches.delete(name))
            );
        }).then(() => self.clients.claim())
    );
});

// Fetch: cache-first for Pyodide, network-first for app
self.addEventListener('fetch', (event) => {
    const url = new URL(event.request.url);

    // Cache-first for Pyodide CDN files
    if (url.hostname === 'cdn.jsdelivr.net' && url.pathname.includes('pyodide')) {
        event.respondWith(
            caches.open(PYODIDE_CACHE).then(cache => {
                return cache.match(event.request).then(response => {
                    if (response) {
                        return response;
                    }
                    return fetch(event.request).then(networkResponse => {
                        if (networkResponse.ok) {
                            cache.put(event.request, networkResponse.clone());
                        }
                        return networkResponse;
                    });
                });
            })
        );
        return;
    }

    // Cache-first for local static files
    if (url.origin === location.origin && url.pathname.startsWith('/static/')) {
        event.respondWith(
            caches.open(CACHE_VERSION).then(cache => {
                return cache.match(event.request).then(response => {
                    return response || fetch(event.request).then(networkResponse => {
                        if (networkResponse.ok) {
                            cache.put(event.request, networkResponse.clone());
                        }
                        return networkResponse;
                    });
                });
            })
        );
        return;
    }

    // Network-first for everything else
    event.respondWith(
        fetch(event.request).catch(() => caches.match(event.request))
    );
});
